<?php
namespace App\Features\Post\Controllers;
use App\Http\Controllers\Controller;use App\Features\Post\Models\Post;use App\Features\Post\Services\PostService;use App\Features\Post\Services\PostExcelService;use App\Features\Ai\Services\OpenAiPostGeneratorService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Validation\Rule;use Inertia\Inertia;
class PostController extends Controller {public function index(Request $r){$q=$r->user()->posts();$posts=$q->latest()->paginate(10)->withQueryString();$all=$r->user()->posts();return Inertia::render('Post/Index',['posts'=>$posts,'stats'=>['total'=>(clone $all)->count(),'published'=>(clone $all)->where('is_published',true)->count(),'draft'=>(clone $all)->where('is_published',false)->count()]]);}public function store(Request $r,PostService $service){$data=$this->validatePost($r);$service->create($r->user(),$data);return back()->with('success','Artikel berhasil dibuat.');}public function show(Post $post){$this->authorize('view',$post);return Inertia::render('Post/Show',['post'=>$post->load('user')]);}public function update(Request $r,Post $post,PostService $service){$this->authorize('update',$post);$service->update($post,$this->validatePost($r));return back()->with('success','Artikel berhasil diperbarui.');}public function destroy(Post $post){$this->authorize('delete',$post);if($post->cover_image_path)Storage::disk('public')->delete($post->cover_image_path);$post->delete();return redirect('/dashboard/posts')->with('success','Artikel berhasil dihapus.');}public function publish(Post $post,PostService $service){$this->authorize('update',$post);$service->toggle($post);return back()->with('success','Status publikasi diperbarui.');}public function cover(Request $r,Post $post){$this->authorize('update',$post);$r->validate(['cover'=>'required|image|mimes:jpg,jpeg,png,webp|max:5120']);if($post->cover_image_path)Storage::disk('public')->delete($post->cover_image_path);$path=$r->file('cover')->store('covers','public');$post->update(['cover_image_path'=>$path]);return back()->with('success','Cover berhasil diunggah.');}public function removeCover(Post $post){$this->authorize('update',$post);if($post->cover_image_path)Storage::disk('public')->delete($post->cover_image_path);$post->update(['cover_image_path'=>null]);return back()->with('success','Cover dihapus.');}public function export(Request $r,PostExcelService $excel){return $excel->export($r->user()->posts()->latest(),'artikel-pribadi.xlsx');}public function import(Request $r,PostExcelService $excel){$r->validate(['file'=>'required|file|mimes:xlsx,xls,csv|max:10240']);$count=$excel->import($r->file('file')->getRealPath(),$r->user());return back()->with('success',"{$count} artikel berhasil diimpor.");}public function generate(Request $r,OpenAiPostGeneratorService $ai){$data=$r->validate(['topic'=>'required|string|max:200','category'=>['required',Rule::in(array_map(fn($c)=>$c->value,\App\Features\Post\Enums\PostCategory::cases()))],'count'=>'required|integer|min:1|max:5']);try{$articles=$ai->generate($data['topic'],$data['category'],$data['count']);return back()->with('generatedArticles',$articles);}catch(\Throwable $e){return back()->withErrors(['ai'=>$e->getMessage()]);}}public function saveGenerated(Request $r,PostService $service){$data=$r->validate(['articles'=>'required|array|min:1|max:5','articles.*.title'=>'required|string|max:250','articles.*.category'=>['required',Rule::in(array_map(fn($c)=>$c->value,\App\Features\Post\Enums\PostCategory::cases()))],'articles.*.excerpt'=>'nullable|string','articles.*.content'=>'required|string']);foreach($data['articles'] as $article)$service->create($r->user(),$article+['is_published'=>false]);return redirect('/dashboard/posts')->with('success','Draft hasil AI berhasil disimpan.');}private function validatePost(Request $r):array{return $r->validate(['title'=>'required|string|max:250','category'=>['required',Rule::in(array_map(fn($c)=>$c->value,\App\Features\Post\Enums\PostCategory::cases()))],'excerpt'=>'nullable|string|max:1000','content'=>'required|string|min:20','is_published'=>'sometimes|boolean']);}}
